mapper.select:
SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, u.phonenumber, u.company_id AS companyId, c.company_name AS companyName, u.is_buyer AS isBuyer, u.is_seller AS isSeller, u.user_type AS userType, u.is_admin AS isAdmin, u.is_deleted AS isDeleted, u.create_time AS createTime FROM sys_user u LEFT JOIN bus_company c ON c.id = u.company_id AND (c.is_deleted IS NULL OR c.is_deleted = 0) WHERE u.del_flag = '0'
AND ( u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY u.user_id DESC LIMIT #{offset}, #{size}

SELECT c.id, c.company_name AS companyName, c.company_type AS companyType, c.owner_user_id AS ownerUserId, u.nick_name AS ownerName, c.contacts, c.phone, c.province, c.city, c.district, IFNULL(c.verified_status, 0) AS verifiedStatus, c.create_time AS createTime FROM bus_company c LEFT JOIN sys_user u ON u.user_id = c.owner_user_id AND u.del_flag = '0' WHERE (c.is_deleted IS NULL OR c.is_deleted = 0)
AND ( c.company_name LIKE CONCAT('%', #{keyword}, '%') OR c.contacts LIKE CONCAT('%', #{keyword}, '%') )
AND IFNULL(c.verified_status, 0) = #{status}
ORDER BY c.id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM bus_company c WHERE (c.is_deleted IS NULL OR c.is_deleted = 0)
AND ( c.company_name LIKE CONCAT('%', #{keyword}, '%') OR c.contacts LIKE CONCAT('%', #{keyword}, '%') )
AND IFNULL(c.verified_status, 0) = #{status}

SELECT s.id, s.category_name AS categoryName, s.company_id AS companyId, c.company_name AS companyName, s.ex_factory_price AS price, '元/吨' AS priceUnit, s.quantity, '吨' AS quantityUnit, s.status, s.create_time AS createTime FROM bus_supply s LEFT JOIN bus_company c ON c.id = s.company_id AND (c.is_deleted IS NULL OR c.is_deleted = 0) WHERE (s.is_deleted IS NULL OR s.is_deleted = 0)
AND ( s.category_name LIKE CONCAT('%', #{keyword}, '%') OR c.company_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY s.id DESC LIMIT #{offset}, #{size}

SELECT r.id, r.category_name AS categoryName, r.company_id AS companyId, c.company_name AS companyName, r.expected_price AS price, '元/吨' AS priceUnit, r.quantity, '吨' AS quantityUnit, r.status, r.create_time AS createTime FROM bus_requirement r LEFT JOIN bus_company c ON c.id = r.company_id AND (c.is_deleted IS NULL OR c.is_deleted = 0) WHERE (r.is_deleted IS NULL OR r.is_deleted = 0)
AND ( r.category_name LIKE CONCAT('%', #{keyword}, '%') OR c.company_name LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY r.id DESC LIMIT #{offset}, #{size}

SELECT p.id, p.title, p.user_id AS authorId, u.nick_name AS authorName, (SELECT COUNT(*) FROM bus_post_like l WHERE l.post_id = p.id) AS likeCount, (SELECT COUNT(*) FROM bus_post_comment pc WHERE pc.post_id = p.id AND (pc.is_deleted IS NULL OR pc.is_deleted = 0)) AS commentCount, p.is_deleted AS isDeleted, p.create_time AS createTime FROM bus_post p LEFT JOIN sys_user u ON u.user_id = p.user_id AND u.del_flag = '0' WHERE 1=1
AND p.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY p.id DESC LIMIT #{offset}, #{size}

SELECT o.id, o.order_no AS orderNo, o.user_id AS userId, u.nick_name AS nickName, u.phonenumber, o.points, COALESCE(o.pay_channel, '-') AS payChannel, o.status, o.create_time AS createTime, o.pay_time AS payTime FROM bus_recharge_order o LEFT JOIN sys_user u ON u.user_id = o.user_id AND u.del_flag = '0' WHERE o.is_deleted = 0
AND ( u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY o.id DESC LIMIT #{offset}, #{size}

SELECT o.user_id AS userId, u.nick_name AS nickName, u.phonenumber, COUNT(*) AS rechargeCount, SUM(o.amount) AS totalAmount, MAX(o.pay_time) AS lastRechargeTime FROM bus_recharge_order o LEFT JOIN sys_user u ON u.user_id = o.user_id AND u.del_flag = '0' WHERE o.status = 1 AND o.is_deleted = 0
AND ( u.nick_name LIKE CONCAT('%', #{keyword}, '%') OR u.phonenumber LIKE CONCAT('%', #{keyword}, '%') )
GROUP BY o.user_id, u.nick_name, u.phonenumber ORDER BY totalAmount DESC LIMIT #{offset}, #{size}
